fn sum_7x9(nums: &Vec<Option<Int>>) -> Option<Int> {
    let mut total = None
    for x in nums {
        match x {
            Some(y) => {
                if y % 7 == 0 || y % 9 == 0 {
                    total = match total {
                        Some(z) => Some(z + y),
                        None => Some(y),
                    }
                }
            },
            None => continue_opt(),
        }
    }
    total
}

fn count_7x9(nums: &Vec<Option<Int>>) -> Option<Int> {
    let mut count = None
    for x in nums {
        match x {
            Some(y) => {
                if y % 7 == 0 || y % 9 == 0 {
                    count = match count {
                        Some(z) => Some(z + 1),
                        None => Some(1),
                    }
                }
            },
            None => continue_opt(),
        }
    }
    count
}

